-- RALLY 100 v2 — APPLY: automatic team joining for new sign-ups. Paste this
-- whole file into the Supabase SQL editor (as postgres) and run it once,
-- AFTER v1 (APPLY_rally100_v1.sql). GENERATED by rally-100/db/build-apply.sh
-- from db/migrations/1002_rally100_auto_join.sql; edit the migration, never
-- this.
--
-- ALL OR NOTHING. It is one transaction: if any statement fails, nothing is
-- left behind. It creates and alters objects inside schema rally100 only.
-- Without v1 it stops at its first statement; it is not re-runnable either:
-- a second run stops at `create table rally100.settings`. Both change nothing.
--
-- WHAT IT SWITCHES ON. With exactly one team that has an owner on it, new
-- sign-ups who confirm their email join that team as reps from the moment
-- this commits, and joining the team lets them see RALLY team data. With no
-- such team, or two or more, the switch starts off. The Owner Dashboard
-- shows the switch and turns it off or on at any time.
--
-- AFTER IT COMMITS:
--   1. Check: the same count as v1's check must now answer 42.
--   2. `select auto_join_team from rally100.settings;` is your team's id
--      (on) or null (off).
--   3. `select count(*) from auth.users where email_confirmed_at is not null;`
--      answers without an error and is not 0 (v2 reads that column to
--      decide who counts as confirmed).
-- TO UNDO: rally-100/db/ROLLBACK_rally100_v2.sql (removes automatic joining
-- only; people it already placed stay on the team).

begin;

-- RALLY 100 v2 — automatic team joining for new sign-ups.
--
-- WHAT THIS FILE IS. The second RALLY 100 migration. It lands on a database
-- where 1001_rally100_v1.sql is already live (1001 is never edited:
-- production ran it) and adds the owner's switch for placing new sign-ups:
--   * rally100.settings, one row holding the switch;
--   * rally100.join_team(), which puts a signed-in, enabled, email-confirmed
--     rep who has no team on the team the switch names;
--   * rally100.set_auto_join(on), the owner's switch;
--   * whoami() and owner_state() replaced in place (same signatures, same
--     grants, still STABLE) so the app can see the switch.
-- The API becomes forty-two functions (rally-100/app/API.md section 6).
--
-- WHOSE DECISION THIS IS. RALLY's 0001 makes team placement a server-side
-- act ("role/team_id/disabled cannot be self-served"), so until now a new
-- account waited on "Almost there" until the owner ran one line of SQL. The
-- owner asked for new sign-ups to join the team without that step, was
-- told that joining the team also opens RALLY's team data (customers, pins,
-- territories) to anyone who signs up and confirms an email address, and
-- chose it. This file builds that choice with guards and an off switch; it
-- does not make the choice. join_team stays a server-side act in every way
-- that matters: the client only asks, and the server decides whether the
-- caller qualifies, which team, and that nothing but team_id changes.
--
-- WHAT IT TOUCHES IN RALLY. No object: nothing outside schema rally100 is
-- created or altered, and db/test/run-tests.sh proves the catalog outside
-- rally100 identical before and after every install and rollback. In DATA it
-- does one thing 1001 never does: join_team WRITES public.profiles.team_id,
-- only on the caller's own row, only from null to the switch's team, and only
-- for an enabled rep whose email is confirmed (RALLY's own profiles_touch
-- trigger stamps updated_at, as on any update). It never writes role or
-- disabled. It also READS auth.users.email_confirmed_at, which Supabase's
-- auth sets when the address is confirmed; if that read ever returned
-- nothing, every caller would count as unconfirmed and nobody would be
-- placed. The switch's team is a plain uuid, for 1001's reason (a foreign
-- key would install triggers on RALLY's table), so it is checked to exist
-- every time it is read.
--
-- THE SWITCH. On always means the team of the owner who turned it on; off is
-- null. A join and a change of the switch never overlap: join_team holds a
-- share lock on the settings row and set_auto_join updates that row, so a
-- change waits for any join already under way, and every join that starts
-- after it commits sees it. Once "off" returns, nobody more is placed.
--
-- UNDO. rally-100/db/ROLLBACK_rally100_v2.sql removes everything below and
-- puts 1001's whoami and owner_state back exactly. It takes nobody off a
-- team: placements already made stay, and removing someone from a team is
-- the owner's act, as it always was.

-- ================================================================= table ===
/* The owner's switch. auto_join_team is the team a qualifying sign-up joins;
   null means off. The boolean key admits exactly one row. updated_by is null
   only for the starting position this file writes. */
create table rally100.settings (
  id             boolean primary key default true check (id),
  auto_join_team uuid,
  updated_at     timestamptz not null default clock_timestamp(),
  updated_by     uuid
);
-- RLS with no policy, as for every rally100 table: functions only.
alter table rally100.settings enable row level security;

/* THE STARTING POSITION. The owner already decided: new sign-ups join the
   owner's team. When that decision has exactly one place to land (one team
   with an owner on it) the switch starts ON for that team, so applying this
   file is all it takes. With no owner on a team, or owners on two or more
   teams, "which team" has no single answer, so it starts OFF and waits for
   the owner to turn it on from the dashboard (which names the owner's own
   team). The starting position goes into the audit log like every later
   change, with no actor: this file set it, not a person. */
with owner_teams as (
  select distinct p.team_id
    from public.profiles p
   where p.role = 'owner' and p.team_id is not null
)
insert into rally100.settings (auto_join_team)
select case when (select count(*) from owner_teams) = 1 then (select o.team_id from owner_teams o) end;

insert into rally100.audit (actor, team_id, entity, entity_id, action, detail)
select null, s.auto_join_team, 'settings', null,
       case when s.auto_join_team is null then 'auto_join_off' else 'auto_join_on' end,
       jsonb_build_object('team_id', s.auto_join_team, 'initial', true)
  from rally100.settings s;

-- ========================================================== helpers ===
/* The team the switch names, if it is on AND that team still exists; null
   otherwise. Everything that reads the switch reads it through here, so "on"
   can never mean a team that is gone. */
create function rally100._auto_join_team()
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select s.auto_join_team
    from rally100.settings s
   where s.auto_join_team is not null
     and exists (select 1 from public.teams t where t.id = s.auto_join_team)
$$;

/* Why join_team would refuse this caller right now, or null when it would
   place them: the switch, then the role, then the email, in join_team's
   order. whoami's auto_join flag is exactly "this is null", so the flag and
   the function can never disagree. The caller is already known to be signed
   in, enabled and on no team.
   Only a rep is ever placed: RALLY's signup trigger makes every new account
   a rep, so a leader, manager or owner without a team is not a new sign-up,
   and is placed by a person. */
create function rally100._join_refusal(p_me public.profiles)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select case
           when rally100._auto_join_team() is null then 'auto_join_off'
           when p_me.role <> 'rep' then 'not_allowed'
           when not exists (select 1 from auth.users u
                             where u.id = p_me.id and u.email_confirmed_at is not null) then 'email_not_confirmed'
         end
$$;

-- The switch as the owner sees it: {on, team_id, team_name}.
create function rally100._auto_join_json()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
           'on', x.team is not null,
           'team_id', x.team,
           'team_name', (select t.name from public.teams t where t.id = x.team))
    from (select rally100._auto_join_team() as team) x
$$;

-- =================================================================== API ===
-- ------------------------------------------------------------ 6.1 everyone

/* whoami, exactly as 1001 wrote it but for one key: a caller with no team
   also learns whether join_team would place them right now (auto_join), so
   the app knows whether to ask for a place or to show "Almost there". */
create or replace function rally100.whoami()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid  pg_catalog.uuid := auth.uid();
  v_me   public.profiles;
  v_user pg_catalog.jsonb;
begin
  if v_uid is null then
    raise exception 'rally100: not signed in' using errcode = '42501';
  end if;
  select * into v_me from public.profiles where id = v_uid;
  if not found then
    raise exception 'rally100: not signed in' using errcode = '42501';
  end if;
  if v_me.disabled then
    raise exception 'rally100: disabled' using errcode = '42501';
  end if;
  v_user := pg_catalog.jsonb_build_object(
    'id', v_me.id, 'name', rally100._name(v_me.id), 'email', v_me.email, 'role', v_me.role,
    'team_id', v_me.team_id,
    'team_name', (select t.name from public.teams t where t.id = v_me.team_id));
  if v_me.team_id is null then
    return pg_catalog.jsonb_build_object('user', v_user, 'no_team', true,
                                         'auto_join', rally100._join_refusal(v_me) is null);
  end if;
  return pg_catalog.jsonb_build_object(
    'user', v_user,
    'ack_version_required', 1,
    'ack_accepted', exists (select 1 from rally100.acks a where a.rep_id = v_me.id and a.version = 1));
end $$;

/* JOIN THE TEAM THE SWITCH NAMES. The one API function that does not start
   with _caller(), because its whole point is a caller with no team. It makes
   _caller()'s first two refusals itself, in the same order and spelling,
   then:
     already on a team       -> {joined:false, already:true, team_id}; nothing changes
     switch off / team gone  -> auto_join_off
     not a rep               -> not_allowed
     email not confirmed     -> email_not_confirmed
   The settings row is read under a share lock (see THE SWITCH above). The
   write names only the caller's own row and repeats the guards it relies on
   (still no team, still a rep, still enabled), so a double tap, a second
   phone or the owner placing the person by hand at the same moment changes
   the row once: the call that finds it already placed answers already.
   Only team_id is written. */
create function rally100.join_team()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid  pg_catalog.uuid := auth.uid();
  v_me   public.profiles;
  v_team pg_catalog.uuid;
  v_why  pg_catalog.text;
begin
  if v_uid is null then
    raise exception 'rally100: not signed in' using errcode = '42501';
  end if;
  select * into v_me from public.profiles where id = v_uid;
  if not found then
    raise exception 'rally100: not signed in' using errcode = '42501';
  end if;
  if v_me.disabled then
    raise exception 'rally100: disabled' using errcode = '42501';
  end if;
  if v_me.team_id is not null then
    return pg_catalog.jsonb_build_object('joined', false, 'already', true, 'team_id', v_me.team_id);
  end if;

  perform 1 from rally100.settings s for share;
  v_why := rally100._join_refusal(v_me);
  if v_why is not null then
    raise exception 'rally100: %', v_why using errcode = '42501';
  end if;
  v_team := rally100._auto_join_team();
  if v_team is null then  -- the team itself went away between the two reads
    raise exception 'rally100: auto_join_off' using errcode = '42501';
  end if;

  update public.profiles p
     set team_id = v_team
   where p.id = v_uid and p.team_id is null and p.role = 'rep' and not p.disabled;
  if not found then
    -- something changed the row since it was read: answer for the row as it is now
    select * into v_me from public.profiles where id = v_uid;
    if not found then
      raise exception 'rally100: not signed in' using errcode = '42501';
    end if;
    if v_me.disabled then
      raise exception 'rally100: disabled' using errcode = '42501';
    end if;
    if v_me.team_id is not null then
      return pg_catalog.jsonb_build_object('joined', false, 'already', true, 'team_id', v_me.team_id);
    end if;
    raise exception 'rally100: not_allowed' using errcode = '42501';
  end if;

  perform rally100._audit(v_uid, v_team, 'rep', v_uid, 'auto_joined',
                          pg_catalog.jsonb_build_object('team_id', v_team));
  return pg_catalog.jsonb_build_object(
    'joined', true, 'team_id', v_team,
    'team_name', (select t.name from public.teams t where t.id = v_team));
end $$;

-- -------------------------------------------------------------- 6.4 owner

/* The owner's switch. On always means the CALLER's own team: there is no
   team parameter, so a stale screen or a mistyped id can never point new
   sign-ups at a team the owner did not mean. The row lock taken here waits
   for any join already holding its share lock. Every change is audited with
   the team it replaced, even when it changes nothing. */
create function rally100.set_auto_join(p_on boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me  public.profiles := rally100._caller();
  v_was pg_catalog.uuid;
  v_to  pg_catalog.uuid;
begin
  perform rally100._require_owner(v_me);
  if p_on is null then
    perform rally100._fail('invalid_payload');
  end if;
  v_to := case when p_on then v_me.team_id end;
  select s.auto_join_team into v_was from rally100.settings s for update;
  insert into rally100.settings (id, auto_join_team, updated_at, updated_by)
  values (true, v_to, pg_catalog.clock_timestamp(), v_me.id)
  on conflict (id) do update
     set auto_join_team = excluded.auto_join_team,
         updated_at     = excluded.updated_at,
         updated_by     = excluded.updated_by;
  perform rally100._audit(v_me.id, v_me.team_id, 'settings', null,
                          case when p_on then 'auto_join_on' else 'auto_join_off' end,
                          pg_catalog.jsonb_build_object('team_id', v_to, 'was_team_id', v_was));
  return rally100._auto_join_json();
end $$;

/* owner_state, exactly as 1001 wrote it but for one key: auto_join, the
   switch as set_auto_join returns it. */
create or replace function rally100.owner_state()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
begin
  perform rally100._require_owner(v_me);
  return pg_catalog.jsonb_build_object(
    'totals', pg_catalog.jsonb_build_object(
      'reps', (select pg_catalog.count(*) from public.profiles p
                where p.team_id is not null and p.role = 'rep' and not p.disabled),
      'persons', (select pg_catalog.count(*) from rally100.persons p where p.merged_into is null),
      'counted', (select coalesce(pg_catalog.sum(c.o_count), 0)
                    from (select distinct e.rep_id from rally100.entries e) x
                    cross join lateral rally100._rep_counts(x.rep_id) c),
      'introductions', (select pg_catalog.count(*) from rally100.introductions i where i.status = 'introduced'),
      'signed', (select pg_catalog.count(*) from rally100.rewards r
                  where r.kind = 'referral' and r.rep_id is not null and r.reversed_at is null)),
    'reps', (select coalesce(pg_catalog.jsonb_agg(rally100._rep_row(p.id, true) order by rally100._name(p.id), p.id),
                             '[]'::pg_catalog.jsonb)
               from public.profiles p where p.team_id is not null),
    'funnel', (select pg_catalog.jsonb_object_agg(s.stage,
                        (select pg_catalog.count(*) from rally100.persons p
                          where p.merged_into is null and p.stage = s.stage))
                 from pg_catalog.unnest(array['added','intro_planned','introduced','meeting_scheduled',
                        'meeting_completed','commitment_confirmed','agreement_signed','start_confirmed',
                        'arrived']::pg_catalog.text[]) s(stage)),
    'outcomes', (select pg_catalog.jsonb_object_agg(o.outcome,
                          (select pg_catalog.count(*) from rally100.persons p
                            where p.merged_into is null and p.outcome = o.outcome))
                   from pg_catalog.unnest(array['follow_up','not_interested','do_not_contact']::pg_catalog.text[]) o(outcome)),
    'rewards', (select pg_catalog.jsonb_object_agg(st.status, pg_catalog.jsonb_build_object(
                         'count', (select pg_catalog.count(*) from rally100.rewards r
                                    where r.status = st.status and r.reversed_at is null),
                         'amount_cents', (select coalesce(pg_catalog.sum(r.amount_cents), 0) from rally100.rewards r
                                           where r.status = st.status and r.reversed_at is null)))
                  from pg_catalog.unnest(array['in_progress','ready','needs_correction','approved','paid']::pg_catalog.text[]) st(status)),
    'payments', (select coalesce(pg_catalog.jsonb_agg(x.obj order by x.paid_on desc, x.updated_at desc), '[]'::pg_catalog.jsonb)
                   from (select r.paid_on, r.updated_at, pg_catalog.jsonb_build_object(
                                  'reward_id', r.id, 'kind', r.kind, 'rep_id', r.rep_id,
                                  'rep_name', rally100._name(r.rep_id),
                                  'person_name', case when r.person_id is not null then rally100._person_name(r.person_id) end,
                                  'incentive_name', (select i.name from rally100.incentives i where i.id = r.incentive_id),
                                  'amount_cents', r.amount_cents, 'paid_on', r.paid_on, 'paid_method', r.paid_method,
                                  'paid_reference', r.paid_reference, 'paid_by_name', rally100._name(r.paid_by),
                                  'reversed', r.reversed_at is not null) as obj
                           from rally100.rewards r where r.status = 'paid'
                          order by r.paid_on desc, r.updated_at desc limit 50) x),
    'leaders', (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                         'id', l.id, 'name', rally100._name(l.id),
                         'team_name', (select t.name from public.teams t where t.id = l.team_id),
                         'open_items', (select (select pg_catalog.sum(pg_catalog.jsonb_array_length(q.value))
                                                  from pg_catalog.jsonb_each(rally100._queues(l)) q))::integer)
                         order by rally100._name(l.id), l.id), '[]'::pg_catalog.jsonb)
                  from public.profiles l
                 where l.role in ('leader', 'manager') and l.team_id is not null and not l.disabled),
    'pending_signups', (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                                 'id', p.id, 'name', rally100._name(p.id), 'email', p.email,
                                 'created_at', p.created_at) order by p.created_at, p.id), '[]'::pg_catalog.jsonb)
                          from public.profiles p where p.team_id is null and not p.disabled),
    'auto_join', rally100._auto_join_json(),
    'incentives', (select coalesce(pg_catalog.jsonb_agg(rally100._incentive_json(i.id) order by i.created_at, i.id),
                                   '[]'::pg_catalog.jsonb)
                     from rally100.incentives i));
end $$;

-- ============================================================= privileges ===
/* As in 1001: the floor first, then the doors. Only what this file creates
   is named, so every grant 1001 made stays exactly as it is. whoami and
   owner_state keep theirs because CREATE OR REPLACE never changes a
   function's owner or privileges. service_role is named for 1001's reason:
   a project's default privileges can hand it every new object. */
revoke all on table rally100.settings                          from public, anon, authenticated, service_role;
revoke all on function rally100._auto_join_team()              from public, anon, authenticated, service_role;
revoke all on function rally100._join_refusal(public.profiles) from public, anon, authenticated, service_role;
revoke all on function rally100._auto_join_json()              from public, anon, authenticated, service_role;
revoke all on function rally100.join_team()                    from public, anon, authenticated, service_role;
revoke all on function rally100.set_auto_join(boolean)         from public, anon, authenticated, service_role;

-- The two new API functions of API.md section 6, and nothing else: the API
-- is now forty-two functions.
grant execute on function rally100.join_team()                 to authenticated;
grant execute on function rally100.set_auto_join(boolean)      to authenticated;

commit;
